import { test, expect } from '@playwright/test';

test.describe('Account Deletion Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/account');
  });

  test('should successfully delete account after confirming with password', async ({ page }) => {
    // Setup: Navigate to account page
    await page.getByRole('heading', { name: /account/i }).click();

    // Verify account details are visible
    const accountName = page.getByText('John Doe');
    await expect(accountName).toBeVisible();

    // Verify delete button is visible
    const deleteButton = page.getByRole('button', { name: /delete account/i });
    await expect(deleteButton).toBeVisible();

    // Click delete button
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmModal).toBeVisible();

    // Verify confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button
    await confirmButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/account deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to login page
    const loginPage = page.getByRole('main', { name: /login/i });
    await expect(loginPage).toBeVisible();

    // Verify account name is no longer visible
    await expect(accountName).not.toBeVisible();

    // Verify delete button is no longer visible
    await expect(deleteButton).not.toBeVisible();
  });

  test('should display error when password is incorrect during account deletion confirmation', async ({ page }) => {
    // Setup: Navigate to account page
    await page.getByRole('heading', { name: /account/i }).click();

    // Verify account details are visible
    const accountName = page.getByText('John Doe');
    await expect(accountName).toBeVisible();

    // Verify delete button is visible
    const deleteButton = page.getByRole('button', { name: /delete account/i });
    await expect(deleteButton).toBeVisible();

    // Click delete button
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmModal).toBeVisible();

    // Verify confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button with incorrect password
    const wrongPasswordInput = page.getByLabel(/password/i);
    await wrongPasswordInput.fill('wrongpassword');

    // Click confirm button
    await confirmButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/incorrect password/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is redirected back to account page
    const accountPage = page.getByRole('main', { name: /account/i });
    await expect(accountPage).toBeVisible();

    // Verify account name is still visible
    await expect(accountName).toBeVisible();

    // Verify delete button is still visible
    await expect(deleteButton).toBeVisible();
  });
});
